Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma rs_A : forall regs m (s pixd pixs comp : Z) (vd vs : pixv) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd)%Z -> (1 <= pixs)%Z -> PIXat m pixd vd -> PIXat m pixs vs ->
    (pixd + 64 <= s - 80)%Z -> (pixs + 64 <= s - 80)%Z -> p_d vd = 32%Z -> p_d vs = 8%Z -> (0 <= comp <= 2)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 11 = Z_to_bv 64 pixs -> getr regs 12 = Z_to_bv 64 comp ->
    exists regs',
      msteps SEGS (mkst regs (0x1adf0 : word) m rom) (mkst regs' (0x1af48 : word) (FRM8 m s ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 19 = Z_to_bv 64 pixd /\ getr regs' 20 = Z_to_bv 64 comp
      /\ regs_agree (fun x => In x [1; 2; 8; 10; 11; 19; 20]%list) regs regs'.
