  (* [comment removed for export] *)
  Lemma rs_B : forall regs m (s pixd pixs comp : Z) (vd vs : pixv),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd)%Z -> (1 <= pixs)%Z -> PIXat m pixd vd -> PIXat m pixs vs ->
    (pixd + 64 <= s - 80)%Z -> (pixs + 64 <= s - 80)%Z -> p_w vd = p_w vs -> p_h vd = p_h vs -> (0 <= comp <= 2)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 pixs -> getr regs 19 = Z_to_bv 64 pixd -> getr regs 20 = Z_to_bv 64 comp ->
    exists regs',
      msteps SEGS (mkst regs (0x1af48 : word) m rom)
                  (mkst regs' (0x1b004 : word) (DIM2c (DIM2c m (s - 68) (s - 72) (p_w vs) (p_h vs)) (s - 76) (s - 80) (p_w vs) (p_h vs)) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 19 = Z_to_bv 64 pixd /\ getr regs' 20 = Z_to_bv 64 comp
      /\ getr regs' 21 = Z_to_bv 64 (p_w vs) /\ getr regs' 22 = Z_to_bv 64 (p_h vs)
      /\ regs_agree (fun x => In x [1; 10; 11; 12; 13; 14; 21; 22]%list) regs regs'.
