  (* [comment removed for export] *)
  Lemma rs_C : forall regs m (s pixd pixs comp w h : Z) (vd vs : pixv),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd)%Z -> (1 <= pixs)%Z -> PIXat m pixd vd -> PIXat m pixs vs -> (1 <= h)%Z -> (0 <= w < 2 ^ 31)%Z -> (h < 2 ^ 31)%Z ->
    (0 <= comp <= 2)%Z ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 pixs -> getr regs 19 = Z_to_bv 64 pixd -> getr regs 20 = Z_to_bv 64 comp ->
    getr regs 21 = Z_to_bv 64 w -> getr regs 22 = Z_to_bv 64 h ->
    exists regs',
      msteps SEGS (mkst regs (0x1b004 : word) m rom) (mkst regs' (0x1b06c : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 9 = Z_to_bv 64 (p_data vd + comp)
      /\ getr regs' 18 = Z_to_bv 64 (p_data vs) /\ getr regs' 8 = Z_to_bv 64 (4 * p_wpl vs) /\ getr regs' 10 = Z_to_bv 64 (4 * p_wpl vd)
      /\ getr regs' 12 = Z_to_bv 64 (p_data vs + w) /\ getr regs' 21 = Z_to_bv 64 w /\ getr regs' 22 = Z_to_bv 64 h /\ getr regs' 19 = Z_to_bv 64 pixd
