  (* [comment removed for export] *)
  Lemma rs_OH : forall regs m (i w ps0 ls ld stride : Z),
    (1 <= w < 2 ^ 31)%Z ->
    getr regs 21 = Z_to_bv 64 w -> getr regs 11 = Z_to_bv 64 i -> getr regs 8 = Z_to_bv 64 stride -> getr regs 12 = Z_to_bv 64 (ps0 + w) ->
    getr regs 9 = Z_to_bv 64 ld -> getr regs 18 = Z_to_bv 64 ls ->
    exists regs',
      msteps SEGS (mkst regs (0x1b06c : word) m rom) (mkst regs' (0x1b080 : word) m rom)
      /\ getr regs' 13 = Z_to_bv 64 (ps0 + w + stride * i) /\ getr regs' 14 = Z_to_bv 64 ld /\ getr regs' 15 = Z_to_bv 64 ls
      /\ regs_agree (fun x => In x [13; 14; 15]%list) regs regs'.
Proof.
