  Lemma rs_I : forall (last : bool) regs m (p q e : Z) (b : byte),
    (0 <= p)%Z -> (p + 8 < 2 ^ 64)%Z -> (0 <= q)%Z -> (q + 8 < 2 ^ 64)%Z -> (0 <= e < 2 ^ 64)%Z -> (if last then p + 1 = e else p + 1 <> e)%Z ->
    m (Z_to_bv 64 (xor3 p)) = Some b -> store_ok SEGS m (Z_to_bv 64 (xor3 q)) 1 = true ->
    getr regs 15 = Z_to_bv 64 p -> getr regs 14 = Z_to_bv 64 q -> getr regs 13 = Z_to_bv 64 e ->
    exists regs',
      msteps SEGS (mkst regs (0x1b080 : word) m rom)
                  (mkst regs' (if last then (0x1b05c : word) else (0x1b080 : word)) (wbytes m (Z_to_bv 64 (xor3 q)) [Z_to_bv 8 (u (Z_to_bv 64 (u b)))]) rom)
      /\ getr regs' 15 = Z_to_bv 64 (p + 1) /\ getr regs' 14 = Z_to_bv 64 (q + 4) /\ getr regs' 13 = Z_to_bv 64 e
      /\ regs_agree (fun x => In x [14; 15; 16; 17]%list) regs regs'.
