    (0 <= ls)%Z -> (0 <= ss)%Z -> (ls + ss < 2 ^ 64)%Z -> (0 <= ld)%Z -> (0 <= sd)%Z -> (ld + sd < 2 ^ 64)%Z ->
    getr regs 11 = Z_to_bv 64 i -> getr regs 22 = Z_to_bv 64 h -> getr regs 18 = Z_to_bv 64 ls -> getr regs 8 = Z_to_bv 64 ss ->
    getr regs 9 = Z_to_bv 64 ld -> getr regs 10 = Z_to_bv 64 sd ->
    exists regs',
      msteps SEGS (mkst regs (0x1b05c : word) m rom) (mkst regs' (if last then (0x1b0a0 : word) else (0x1b06c : word)) m rom)
      /\ getr regs' 11 = Z_to_bv 64 (i + 1) /\ getr regs' 18 = Z_to_bv 64 (ls + ss) /\ getr regs' 9 = Z_to_bv 64 (ld + sd)
      /\ regs_agree (fun x => In x [9; 11; 18]%list) regs regs'.
Proof.
