  (* [comment removed for export] *)
  Lemma rs_E : forall regs r0 m (s : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> cellsZ m (frame8 s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) ->
    exists regs',
      msteps SEGS (mkst regs (0x1b0a0 : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 0
      /\ (forall x, In x [8; 9; 18; 19; 20; 21; 22]%bv -> getr regs' x = getr r0 x)
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 18; 19; 20; 21; 22]%list) regs regs'.
